#include <vector>

using namespace std;

class Solution {
public:
    bool nimGame(vector<int>& piles) {
        int nimSum = 0;
        for (int p : piles) {
            nimSum ^= p;
        }
        return nimSum != 0;
    }
};

class Solution {
    public boolean nimGame(int[] piles) {
        int nimSum = 0;
        for (int p : piles) {
            nimSum ^= p;
        }
        return nimSum != 0;
    }
}

/**
 * @param {number[]} piles
 * @return {boolean}
 */
var nimGame = function(piles) {
    let nimSum = 0;
    for (let i = 0; i < piles.length; ++i) {
        nimSum ^= piles[i];
    }
    return nimSum !== 0;
};
